	// A per-feed refresh interval overrides the interval computed from the global configuration.
	if f.RefreshInterval > 0 {
		interval := time.Duration(f.RefreshInterval) * time.Minute

		// Still honor the delay requested by the server (TTL, Retry-After, Cache-Control, Expires),
		// limited to the global max interval for misconfigured feeds.
		maxDelay := config.Opts.SchedulerRoundRobinMaxInterval()
		if config.Opts.PollingScheduler() == SchedulerEntryFrequency {
			maxDelay = config.Opts.SchedulerEntryFrequencyMaxInterval()
		}
		interval = max(interval, min(refreshDelay, maxDelay))

		f.NextCheckAt = time.Now().Add(interval)
